  "implementation": "def solve(case):
    nodes = case["nodes"]
    core = case["core_distance"]
    distances = case["distances"]
    edges = []
    for u, v, d in distances:
        if u > v:
            u, v = v, u
        mutual = max(core[u], core[v], d)
        edges.append((mutual, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    sorted_nodes = sorted(nodes)
    node_to_idx = {node: i for i, node in enumerate(sorted_nodes)}
    n = len(sorted_nodes)
    parent = list(range(n))
    rank = [0]*n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        xr = find(x)
        yr = find(y)
        if xr == yr:
            return False
        if rank[xr] < rank[yr]:
            xr, yr = yr, xr
        parent[yr] = xr
        if rank[xr] == rank[yr]:
            rank[xr] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    selected = 0
    for w, u, v in edges:
        if selected == n-1:
            break
        iu = node_to_idx[u]
        iv = node_to_idx[v]
        if union(iu, iv):
            mst_edges.append([u, v, w])
            total_weight += w
            selected += 1
    if selected != n-1:
        raise ValueError("Disconnected graph")
    return {"mst_edges": mst_edges, "total_weight": total_weight}
